_GetRhoFromLut = RegularGridInterpolator((S, T, P), rho_lut)

_GetSigma0FromLut = RegularGridInterpolator((S, T, P), sigma0_lut)

def GetRhoFromLut(saln, temp, pres):
    
    if saln > MAX_SALN or saln < MIN_SALN or np.isnan(saln):
        return None
    if temp > MAX_TEMP or temp < MIN_TEMP or np.isnan(temp):
        return None
    if pres > MAX_PRES or np.isnan(pres):
        return None
    if pres < MIN_PRES:
        pres = MIN_PRES

    return round(_GetRhoFromLut([saln, temp, pres])[0], 3)
    
    
def GetSigma0FromLut(saln, temp, pres):
    
    if saln > MAX_SALN or saln < MIN_SALN or np.isnan(saln):
        return None
    if temp > MAX_TEMP or temp < MIN_TEMP or np.isnan(temp):
        return None
    if pres > MAX_PRES or np.isnan(pres):
        return None
    if pres < MIN_PRES:
        pres = MIN_PRES

    return round(_GetSigma0FromLut([saln, temp, pres])[0], 3)
    







